B.KY=s(["\xdcberschlag (freier Fall)"],t.s)
B.N2=s(["Ko-uchi (Barai/Gari)","O-uchi (Barai/Gari)","Tai-otoshi RL","Tani-otoshi RL"],t.s)
B.KS=s(["Ude-hishigi-juji-gatame RL","Ude-garami RL","Uki-gatame"],t.s)
